-- aar/w3/aar_row_588_anchor_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for the ASK 588 question-round anchor fix, as a revision of row 159 (ASK 588 rev 1; prior_row 159), and its ask_aar_builders row.
-- Every value is from Wall 11598 and 11599 (read whole by W3 19:56 CST 2026-11-24), audit_log row 41528 (read whole), odv1_question_round_log rows 1 to 3 (read by SQL 19:56 CST), the AAR of run 42373 draft 6 (item 2), W4's files under /mnt/project-files/ask588/w4/fixqr/ (md5sum by W3; build_fixqr.cjs read whole; the PASS, FAIL and ERROR lines of the two test outputs counted), or W4's thread note to W3 of 19:53 CST (the write card).
-- NOT LOCATED by W3: a Wall post that carries W1's grade of this build. Wall 11598 and audit 41528 name it "W1 PASS (9fc9abd8)", and W1's readback (Wall 11599) names "graded target 857566f6" and "N1 and N2 of my grade". The grades element cites Wall 11599 for that reason. W1: give the grade's own Wall id or file and I enter it.
-- NO PLAN FILE: a defect fix of the ASK 588 build; the objective is W4's statement on Wall 11598.
-- rev is 'F1' (my choice of label for "fix 1"); say if another label is the practice.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (588, 'F1', $t$ASK 588 fix: the question round's transcript anchor (every fresh run skipped the round)$t$,
  $t$The question round finds the transcript inside a judge's request by an anchor. The anchor was "DEBATE TRANSCRIPT", a blank line, then "=== ["; the transcript starts "=== TOPIC ===", so the anchor never matched and every fresh run skipped the question round (run 42234, log row SKIPPED). Make the anchor "DEBATE TRANSCRIPT", a blank line, then "=== ", in QR Merge, QR Follow Build and QR Follow Final, so that a fresh run's question round runs. (W4, Wall 11598; no plan file)$t$,
  'yes',
  $t$Written by W4 at 11:30 CST 2026-11-24 after run 42234 ended, on the operator's press "Write the fix" (10:56 CST), and read back MATCH by W1 (Wall 11598, 11599; audit 41528). Engine 6834c21b to ff7ab4cf; three nodes changed, in each only the constant QR_AT; child untouched. SHOWN BY TWO RUNS: before the fix, run ODV1-42234-501p8uuq stored its question-round log row SKIPPED (row 1); after it, ODV1-42283-f584bu4b stored RAN (row 2, 13:49 CST) and ODV1-42373-tg0w4edj stored RAN (row 3, 17:21 CST). In run 42373 six questions were asked, all six checks passed at the first try, every answer finished, and two judges cite the round (the AAR of 42373, item 2). STATUS IS NOT 'proven by run': run 42283 ended in error at the judges' call (the ASK 611 expression fault), so it is not a run with no issues, and W3 counts one clean run for this fix, 42373. LIMITS: in both runs the answers went by the Anthropic route; the OpenRouter answer route did not run. Where the question-round block stands in each judge's request is in the execution only and is not read (W4's read is owed). The stored test outputs in the build folder each end in an ERROR line and hold a FAIL of T0.8 on the base and on the target alike (see tests); whether W1's grade covered them is for W1 to say.$t$,
  '11598, 11599, 11600, 11875',
  current_setting('truth.session_id'), 159,
  to_jsonb($t$W4's thread, 10:56 CST 2026-11-24: he pressed "Write the fix" on the card "Write the question-round fix once the current run ends?" (card cmsg_017ZQamDMHrS6fqMHnQDVo58VmaMjEfy8jz5rDoYMcjZXc, posted 10:50 CST; options "Write the fix" / "Hold"; from W4's thread note to W3, 19:53 CST; audit 41528 names the card's answer). W3 did not read the card.$t$::text),
  $j${"answer": "Write the fix", "question": "Write the question-round fix once the current run ends?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58VmaMjEfy8jz5rDoYMcjZXc", "options": "Write the fix / Hold", "posted": "10:50 CST 2026-11-24", "press_time": "10:56 CST 2026-11-24", "source": "W4's thread note to W3, 19:53 CST 2026-11-24; audit 41528. Not read by W3."}$j$::jsonb,
  'W4',
  $j${"md5": "none", "path": "none", "note": "NO PLAN FILE. A defect fix of the ASK 588 build, named by W4 as its own defect (Wall 11598). The plan of ASK 588 is in row 159.", "source": "Wall 11598; W4's thread note (\"There is no separate notes file\")"}$j$::jsonb,
  $j$[{"md5": "857566f6", "path": "ask588/w4/fixqr/target_engine_fixqr.json", "note": "the engine target as written", "source": "md5sum by W3; Wall 11599; audit 41528"}, {"md5": "b84c2e62", "path": "ask588/w4/fixqr/build_fixqr.cjs", "note": "the build: in each of the three nodes the one line const QR_AT=... is replaced; it throws unless the old line stands exactly once. Read whole by W3.", "source": "md5sum and read by W3"}, {"md5": "fc9d70fe", "path": "ask588/w4/fixqr/t_fixqr.cjs", "note": "the test", "source": "md5sum by W3"}, {"md5": "46d62ec8", "path": "ask588/w4/fixqr/out_target_engine_fixqr.json.txt", "note": "test output on the target; out_base_eng.json.txt 892ec081 is the output on the base", "source": "md5sum and counted by W3"}, {"md5": "2fe78155", "path": "ask588/w4/fixqr/write_fixqr.sh", "note": "the write script", "source": "md5sum by W3"}, {"md5": "cbf170a6", "path": "ask588/w4/fixqr/standing_at_write.txt", "note": "STANDING: 29 PASS, 0 FAIL at the write", "source": "md5sum and read by W3"}, {"md5": "9efc8e1e", "path": "ask588/w4/fixqr/fetchback_eng_fixqr.json", "note": "engine fetch-back after the write", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"engine": {"path": "ask588/w4/fixqr/revert_eng_fixqr.json", "md5": "39052c09", "note": "the engine before the fix (6834c21b), 423 nodes"}, "order": "NOT A WHOLE-FILE REVERT NOW: many engine writes followed (ASK 601, 611, 608, 607, 623, 579, 611 fix 2, 627, 628, 578). To undo the fix alone, the one line of the three nodes is put back; that would make every fresh run skip the question round again.", "database": "none", "rehearsed": "no", "source": "md5sum and node count by W3; audit 41528"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (the build; named \"W1 PASS (9fc9abd8)\" on Wall 11598 and in audit 41528; W1's readback names the graded target 857566f6 and says N1 and N2 of the grade stay open). The grade's own Wall post was not located by W3; this element cites the readback post.", "wall_id": 11599, "md5_graded": "857566f6", "verdict_norm": "PASS", "source": "Wall 11598, 11599; audit 41528; W1's commit 9fc9abd8 (not read by W3)"}]$j$::jsonb,
  ARRAY['857566f6'], '[41528]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 (engine)", "before": "6834c21b", "after": "ff7ab4cf-f33a-4bad-9eb5-4a06f8c56804 (11:30 CST), active, 423 nodes; changed QR Merge, QR Follow Build and QR Follow Final only: const QR_AT='DEBATE TRANSCRIPT\\n\\n=== [' became const QR_AT='DEBATE TRANSCRIPT\\n\\n=== '; connections the same. Child ecdc6218 untouched."}]$j$::jsonb,
  $j$[{"name": "t_fixqr.cjs, stored outputs", "result": "On the target: 35 lines PASS, 1 FAIL, 1 ERROR. T2.8 (QR Merge: qr_ok, six answers read from both reply shapes) PASSES. The FAIL is T0.8 (QR Merge has one parent and its output is unchanged). The ERROR is a missing file, target_engine_588.json, at the test's last part. On the base: 30 PASS, 2 FAIL (T0.8 and T2.8), 1 ERROR. So T2.8 turns from FAIL to PASS with the fix, and T0.8 fails alike before and after. Counted by W3 from the stored files; not re-run by W3.", "source": "out_target_engine_fixqr.json.txt 46d62ec8; out_base_eng.json.txt 892ec081"}, {"name": "Standing set and pair check at the write", "result": "29 PASS, 0 FAIL; fetch-back parameters and connections equal the target; pair Library Check PASSES (lib 47a39128fec62d31, map efe8431fb6af14e1).", "source": "standing_at_write.txt cbf170a6; Wall 11598, 11599; audit 41528"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (live ff7ab4cf, 423 nodes, 0 differences from the graded target 857566f6; against 6834c21b only the three nodes changed and in each only QR_AT; child untouched; standing 29 PASS, 0 FAIL; pair PASS)", "wall_id": 11599, "source": "Wall 11599"}]$j$::jsonb,
  $j${"case": "THE ROUND RAN ON BOTH FRESH RUNS SINCE THE FIX. One of the two runs is clean.", "runs": [{"run": "ODV1-42234-501p8uuq (before the fix)", "result": "odv1_question_round_log row 1: SKIPPED"}, {"run": "ODV1-42283-f584bu4b", "result": "row 2: RAN, dry false, 13:49 CST 2026-11-24. The run then ended in error at the judges' call (ASK 611); not a clean run."}, {"run": "ODV1-42373-tg0w4edj", "result": "row 3: RAN, dry false, 17:21 CST 2026-11-24. Six questions, three to each side; all six checks passed at the first try; no follow-up; the judges sol62 and sol cite the round (AAR draft 6, item 2)."}], "not_shown": "the OpenRouter answer route; the place of the question-round block in each judge's request (execution only).", "source": "odv1_question_round_log, SQL by W3 19:56 CST 2026-11-24; aar/w3/aar_run42373_draft6.md 6ef38f57 (W1 PASS Wall 11875)"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "no entry for the fix. The manual holds none of the strings \"=== [\", \"QR_AT\" and \"transcript anchor\" (W3's search of engine_manual_full() by SQL, 19:58 CST 2026-11-24), so no entry is made wrong by it."}$j$::jsonb,
  'read back', $j$[11598, 11599, 11600, 11875]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "built and wrote the fix on the operator's card; named the defect as its own", "wall_id": 11598}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
